1	package retention
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"sync"
13		"syscall"
14	)
15	
16	// 状态文件与锁文件的固定名称，位于调用者选择的本地目录内。
17	const (
18		stateFileName = "retention-state.json"
19		lockFileName  = ".retention.lock"
20	)
21	
22	// Store 是一个本地保管库，对应调用者选择的一个本地保存位置。
23	//
24	// 同一个目录可以被本机上的多个程序（进程）同时打开：
25	// 每次办理都会取得跨进程的排他文件锁，并从磁盘重新读取状态，
26	// 因此两个程序对同一档案的冻结、销毁一定有明确的先后顺序。
27	type Store struct {
28		dir string
29	
30		// opMu 串行化当前 Store 实例内的办理；跨进程互斥由文件锁保证。
31		opMu sync.RWMutex
32	}
33	
34	// Open 打开（或创建）一个本地保存位置。
35	// 目录不存在时会创建；状态文件不存在时按空库打开，可以正常登记。
36	// 状态文件已存在但内容损坏（空文件、只有空白、内容为 null、合法对象后面
37	// 还拼接了其他内容等），或其中保存的记录不满足业务不变量（例如已解除冻结
38	// 缺少解除原因或解除日期、解除日期早于冻结日期）时返回 ErrCorruptState，
39	// 不会返回可继续办理的保管库，已有记录保持原样，不会被清空、修补或覆盖。
40	func Open(dir string) (*Store, error) {
41		if dir == "" {
42			return nil, errors.New("retention: 保存位置不能为空")
43		}
44		if err := os.MkdirAll(dir, 0o755); err != nil {
45			return nil, fmt.Errorf("retention: 无法创建保存位置: %w", err)
46		}
47		s := &Store{dir: dir}
48		// 提前读一次，让损坏的状态文件在打开时就暴露，而不是等到第一次办理。
49		if _, err := s.load(); err != nil {
50			return nil, err
51		}
52		return s, nil
53	}
54	
55	// Close 释放保管库。当前实现没有跨操作持有的资源，保留它以稳定公开入口形态。
56	func (s *Store) Close() error { return nil }
57	
58	func (s *Store) statePath() string { return filepath.Join(s.dir, stateFileName) }
59	func (s *Store) lockPath() string  { return filepath.Join(s.dir, lockFileName) }
60	
61	// lock 取得跨进程排他锁，返回解锁函数。
62	// 每次办理各自加锁、解锁，这样同一位置也允许同进程或跨进程的多个 Store 并存。
63	func (s *Store) lock() (func(), error) {
64		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
65		if err != nil {
66			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
67		}
68		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
69			f.Close()
70			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
71		}
72		return func() {
73			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
74			_ = f.Close()
75		}, nil
76	}
77	
78	// rlock 取得跨进程共享锁，用于只读核对。
79	func (s *Store) rlock() (func(), error) {
80		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
81		if err != nil {
82			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
83		}
84		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
85			f.Close()
86			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
87		}
88		return func() {
89			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
90			_ = f.Close()
91		}, nil
92	}
93	
94	// load 从磁盘读取最新状态。文件不存在时返回一份空状态（尚未建立记录）。
95	//
96	// 文件已经存在时，必须完整包含且只包含一个 JSON 对象（前后允许空白）：
97	// 零字节或只有空白的文件、内容为 null 的文件、合法对象后面还拼接了
98	// 第二个 JSON 值或无法解析的文字，都判为损坏并返回 ErrCorruptState，
99	// 绝不只使用前一段内容，也不会改动原文件。
100	//
101	// JSON 能解析不代表记录合法：任何已解除冻结都必须同时带有非空白的
102	// 解除原因和有效的解除日期，且解除日期不早于冻结日期——与解除功能
103	// 办理时的要求一致。缺少任一信息或日期顺序不成立时，整份保管库同样
104	// 判为损坏并返回 ErrCorruptState，错误信息指明涉及的档案与冻结编号。
105	func (s *Store) load() (*storeData, error) {
106		raw, err := os.ReadFile(s.statePath())
107		if err != nil {
108			if errors.Is(err, os.ErrNotExist) {
109				return newStoreData(), nil
110			}
111			return nil, fmt.Errorf("retention: 无法读取状态文件: %w", err)
112		}
113		trimmed := bytes.TrimSpace(raw)
114		if len(trimmed) == 0 {
115			return nil, fmt.Errorf("retention: 状态文件为空或只有空白: %w", ErrCorruptState)
116		}
117		// json.Unmarshal 对 null 不报错且保持目标不变，必须单独拒绝。
118		if string(trimmed) == "null" {
119			return nil, fmt.Errorf("retention: 状态文件内容为 null，不是有效的保管库记录: %w", ErrCorruptState)
120		}
121		data := newStoreData()
122		// json.Unmarshal 要求整个输入恰好是一个 JSON 值：
123		// 合法对象后面再拼接任何内容都会在这里报错。
124		if err := json.Unmarshal(raw, data); err != nil {
125			return nil, fmt.Errorf("retention: 状态文件内容无法解析: %v: %w", err, ErrCorruptState)
126		}
127		if data.Archives == nil {
128			data.Archives = map[string]*archiveRecord{}
129		}
130		if data.Manifests == nil {
131			data.Manifests = map[string]*manifestRecord{}
132		}
133		// 语义校验先于任何兼容处理：已解除冻结必须与既有解除功能遵守同一要求——
134		// 解除原因与解除日期齐备，且解除日期不早于冻结日期。
135		// 只有“已解除”标记而缺少任一信息，或解除日期早于冻结日期的记录
136		// 一律判为损坏（即使所属档案已销毁）；绝不据此继续办理或修补记录。
137		if err := validateFreezeReleaseRecords(data); err != nil {
138			return nil, err
139		}
140		// 兼容引入修订功能之前保存的保管库：没有记录最初截止日时，
141		// 登记截止日就是最初截止日。
142		for _, ar := range data.Archives {
143			if ar.InitialEnd.IsZero() {
144				ar.InitialEnd = ar.End
145			}
146		}
147		return data, nil
148	}
149	
150	// validateFreezeReleaseRecords 检查库内全部已解除冻结记录是否完整合法。
151	//
152	// 正常解除保存的记录必然同时带有非空白的解除原因和有效的解除日期，
153	// 且解除日期不早于冻结日期。缺少解除原因、解除日期缺失或为 null、
154	// 解除日期早于冻结日期，都说明保存内容已损坏，返回可由 ErrCorruptState
155	// 识别的错误，并在信息中给出涉及的档案编号与冻结编号，便于定位记录。
156	// 校验覆盖整个保管库的全部已解除冻结，与本次办理名单无关：
157	// 即使异常记录所属档案已经销毁，也不能把不完整的解除信息当作正常历史。
158	// 未解除冻结没有解除日期和原因是合法状态，不在此报错。
159	func validateFreezeReleaseRecords(data *storeData) error {
160		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
161		archiveIDs := make([]string, 0, len(data.Archives))
162		for id := range data.Archives {
163			archiveIDs = append(archiveIDs, id)
164		}
165		sort.Strings(archiveIDs)
166		for _, id := range archiveIDs {
167			ar := data.Archives[id]
168			if ar == nil {
169				return fmt.Errorf("retention: 档案 %s 的登记记录缺失，状态文件已损坏: %w",
170					id, ErrCorruptState)
171			}
172			for _, fr := range ar.Freezes {
173				if fr == nil {
174					return fmt.Errorf("retention: 档案 %s 下存在缺失的冻结记录，状态文件已损坏: %w",
175						id, ErrCorruptState)
176				}
177				if !fr.Released {
178					// 未解除冻结没有解除日期与原因是合法状态。
179					continue
180				}
181				switch {
182				case strings.TrimSpace(fr.ReleaseReason) == "":
183					return fmt.Errorf(
184						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除原因，记录已损坏: %w",
185						id, fr.ID, ErrCorruptState)
186				case fr.ReleasedOn == nil:
187					return fmt.Errorf(
188						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除日期，记录已损坏: %w",
189						id, fr.ID, ErrCorruptState)
190				case fr.ReleasedOn.IsZero():
191					return fmt.Errorf(
192						"retention: 档案 %s 的冻结 %s 的解除日期无效，记录已损坏: %w",
193						id, fr.ID, ErrCorruptState)
194				case fr.ReleasedOn.Before(fr.FrozenOn):
195					return fmt.Errorf(
196						"retention: 档案 %s 的冻结 %s 的解除日期 %s 早于冻结日期 %s，记录已损坏: %w",
197						id, fr.ID, fr.ReleasedOn, fr.FrozenOn, ErrCorruptState)
198				}
199			}
200		}
201		return nil
202	}
203	
204	// save 原子地写入状态：先写同目录临时文件并刷盘，再 rename 替换，最后刷目录。
205	// 写入过程中崩溃不会留下半截状态，旧文件保持完好。
206	func (s *Store) save(data *storeData) error {
207		buf, err := json.MarshalIndent(data, "", "  ")
208		if err != nil {
209			return fmt.Errorf("retention: 状态编码失败: %w", err)
210		}
211		tmp, err := os.CreateTemp(s.dir, ".retention-state-*.tmp")
212		if err != nil {
213			return fmt.Errorf("retention: 无法创建临时状态文件: %w", err)
214		}
215		tmpName := tmp.Name()
216		cleanup := func() { _ = os.Remove(tmpName) }
217		if _, err := tmp.Write(buf); err != nil {
218			tmp.Close()
219			cleanup()
220			return fmt.Errorf("retention: 写入状态失败: %w", err)
221		}
222		if err := tmp.Sync(); err != nil {
223			tmp.Close()
224			cleanup()
225			return fmt.Errorf("retention: 刷盘状态失败: %w", err)
226		}
227		if err := tmp.Close(); err != nil {
228			cleanup()
229			return fmt.Errorf("retention: 关闭状态文件失败: %w", err)
230		}
231		if err := os.Rename(tmpName, s.statePath()); err != nil {
232			cleanup()
233			return fmt.Errorf("retention: 替换状态文件失败: %w", err)
234		}
235		// 刷目录，确保 rename 在崩溃后仍然落盘。
236		if dir, err := os.Open(s.dir); err == nil {
237			_ = dir.Sync()
238			_ = dir.Close()
239		}
240		return nil
241	}
242	
243	// mutate 在跨进程排他锁内重读状态、办理变更，仅在全部校验通过后写回。
244	// fn 返回错误时绝不写盘，磁盘上的已有记录不受影响。
245	func (s *Store) mutate(fn func(*storeData) error) error {
246		s.opMu.Lock()
247		defer s.opMu.Unlock()
248		unlock, err := s.lock()
249		if err != nil {
250			return err
251		}
252		defer unlock()
253		data, err := s.load()
254		if err != nil {
255			return err
256		}
257		if err := fn(data); err != nil {
258			return err
259		}
260		return s.save(data)
261	}
262	
263	// view 在共享锁内重读状态并执行只读查询。
264	func (s *Store) view(fn func(*storeData) error) error {
265		s.opMu.RLock()
266		defer s.opMu.RUnlock()
267		unlock, err := s.rlock()
268		if err != nil {
269			return err
270		}
271		defer unlock()
272		data, err := s.load()
273		if err != nil {
274			return err
275		}
276		return fn(data)
277	}
