318	// rewriteState 解析已保存状态、按 fn 修改后原样写回（保持 JSON 合法），
319	// 用于模拟保管库打开之后保存内容被改成语义损坏的记录。
320	func rewriteState(t *testing.T, dir string, fn func(map[string]any)) {
321		t.Helper()
322		path := filepath.Join(dir, stateFileName)
323		raw, err := os.ReadFile(path)
324		if err != nil {
325			t.Fatal(err)
326		}
327		var doc map[string]any
328		if err := json.Unmarshal(raw, &doc); err != nil {
329			t.Fatal(err)
330		}
331		fn(doc)
332		out, err := json.MarshalIndent(doc, "", "  ")
333		if err != nil {
334			t.Fatal(err)
335		}
336		if err := os.WriteFile(path, out, 0o600); err != nil {
337			t.Fatal(err)
338		}
339	}
